use crate::aap::caps::kb_read;

struct Node;

/// Maximum question length, in characters, permitted by the contract.
const MAX_QUESTION_CHARS: usize = 512;

/// Used only when the knowledge base returns nothing for every query, so that
/// `knowledge` is always present (non-empty) in the output.
const NO_KNOWLEDGE: &str = "No relevant knowledge-base articles were found for this question.";

fn bound_question(mut question: String) -> String {
    if let Some((idx, _)) = question.char_indices().nth(MAX_QUESTION_CHARS) {
        question.truncate(idx);
    }
    question
}

fn add_results(knowledge: &mut Vec<String>, results: Vec<String>) {
    for entry in results {
        if entry.trim().is_empty() {
            continue;
        }
        if knowledge.iter().any(|k| *k == entry) {
            continue;
        }
        knowledge.push(entry);
    }
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let inner = query.query;
        let intent = inner.intent;
        let question = bound_question(inner.question);

        let mut knowledge: Vec<String> = Vec::new();

        // Primary lookup: the (bounded) question itself.
        if !question.trim().is_empty() {
            add_results(&mut knowledge, kb_read::lookup(&question));
        }

        // Fallback: look up each extracted entity if the question found nothing.
        if knowledge.is_empty() {
            for entity in inner.entities.iter() {
                let entity = entity.trim();
                if entity.is_empty() {
                    continue;
                }
                add_results(&mut knowledge, kb_read::lookup(entity));
            }
        }

        // Guarantee `present(knowledge)`.
        if knowledge.is_empty() {
            knowledge.push(String::from(NO_KNOWLEDGE));
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
